REVOKE ALL ON FUNCTION public.request_invoice_refund(uuid,text) FROM authenticated; REVOKE ALL ON FUNCTION public.review_invoice_refund(uuid,text,text) FROM authenticated;
GRANT EXECUTE ON FUNCTION public.request_invoice_refund(uuid,text) TO service_role; GRANT EXECUTE ON FUNCTION public.review_invoice_refund(uuid,text,text) TO service_role;
CREATE OR REPLACE FUNCTION public.request_invoice_refund(invoice uuid, explanation text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE inv public.billing_invoices; request_id uuid; caller uuid := nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'app_actor'; BEGIN IF caller IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF; SELECT * INTO inv FROM public.billing_invoices WHERE id=invoice AND user_id=caller FOR UPDATE; IF inv.id IS NULL OR inv.status<>'paid' OR inv.environment<>'live' OR inv.amount_paid_minor<=inv.amount_refunded_minor THEN RAISE EXCEPTION 'Invoice is not eligible'; END IF; INSERT INTO public.refund_requests(invoice_id,user_id,reason) VALUES(inv.id,caller,btrim(explanation)) RETURNING id INTO request_id; RETURN request_id; END $$;
CREATE OR REPLACE FUNCTION public.review_invoice_refund(request uuid, decision text, note text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'Use protected application review'; END $$;